def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residuals = bins - item
    return np.where(residuals >= 0, -1 / (1 + np.exp(-residuals ** 2)), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residuals = bins - item
    optimal_residual = 0.05
    return np.where(residuals >= 0, np.exp(-((residuals - optimal_residual) ** 2) / 0.02), -np.inf)

