def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residuals = bins - item
    optimal_residual = 0.05
    width = 0.15
    return np.where(residuals >= 0, np.maximum(0.0, 1.0 - np.abs(residuals - optimal_residual) / width), -np.inf)

